class Emitter {
  #listeners = new Map();   // event name -> array of functions

  on(event, listener) {
    const list = this.#listeners.get(event) ?? [];
    this.#listeners.set(event, [...list, listener]);
    return () => this.off(event, listener);   // unsubscribe handle
  }

  off(event, listener) {
    const list = this.#listeners.get(event) ?? [];
    this.#listeners.set(event, list.filter((l) => l !== listener));
  }

  emit(event, payload) {
    for (const listener of this.#listeners.get(event) ?? []) {
      listener(payload);
    }
  }
}

const cart = new Emitter();
const stop = cart.on("added", (item) => console.log("added", item));
cart.emit("added", "book");   // added book
stop();
cart.emit("added", "pen");    // (nothing)

once(event, listener) {
  const wrapper = (payload) => {
    this.off(event, wrapper);   // remove first, so a throw cannot leave it behind
    listener(payload);
  };
  return this.on(event, wrapper);
}

// Snapshot: on/off above replace the array instead of mutating it,
// so the for...of loop in emit keeps walking the old array.
